
-- Table for temporary PIN codes generated by admins for password recovery
CREATE TABLE public.password_pins (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  pin text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  expires_at timestamp with time zone NOT NULL DEFAULT (now() + interval '24 hours'),
  used boolean NOT NULL DEFAULT false
);

ALTER TABLE public.password_pins ENABLE ROW LEVEL SECURITY;

-- Admins can manage PINs
CREATE POLICY "Admin can manage pins" ON public.password_pins
  FOR ALL TO authenticated
  USING (has_role(auth.uid(), 'admin'::app_role))
  WITH CHECK (has_role(auth.uid(), 'admin'::app_role));

-- Anyone can read pins (needed for login with PIN - validated server-side)
CREATE POLICY "Anon can read valid pins" ON public.password_pins
  FOR SELECT TO anon, authenticated
  USING (true);
